/** Article dates from git history: [datePublished, dateModified] as ISO 8601. Generated by scripts/gen-compendium.ts; {} if absent. */
const files = import.meta.glob<Record<string, [string, string]>>('./generated/dates.json', { eager: true, import: 'default' })
const DATES: Record<string, [string, string]> = Object.values(files)[0] ?? {}

export interface ArticleDates { published: string; modified: string }
export function articleDates(path: string): ArticleDates | undefined {
  const d = DATES[path]
  return d ? { published: d[0], modified: d[1] } : undefined
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
/** "2026-11-26T10:51:19-06:00" -> "November 26, 2026". Reads the date as written, so server and browser agree in any time zone. */
export function formatDate(iso: string): string {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number)
  return `${MONTHS[m - 1]} ${d}, ${y}`
}
